import{_ as o,l,o as t,c as i,v as E,p,x as s,d as r,i as B,S as d,b as a}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"反向压力测试","description":"","frontmatter":{"title":"反向压力测试","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/reverse-stress-test.md","filePath":"quant/reverse-stress-test.md","lastUpdated":1789023840000}'),A={name:"quant/reverse-stress-test.md"};function h(u,e,c,m,g,x){const n=l("Mermaid");return t(),i("div",null,[e[1]||(e[1]=E('<h1 id="反向压力测试" tabindex="-1">反向压力测试 <a class="header-anchor" href="#反向压力测试" aria-label="Permalink to &quot;反向压力测试&quot;">​</a></h1><div class="epigraph"><p>正向压力从情景走到损失；反向压力从「何种损失已经不可接受」走到仍能解释该损失的因子移动，再问这些移动在经济上是否说得通。</p><footer>—— 对照 CEBS, Guidelines on Stress Testing, 2010；BCBS 与各国监管对内部资本程序中反向压力的公开要求</footer></div><p><a href="/quant/stressed-var-frtb">压力 VaR 与 FRTB</a> 把一段历史压力年套在今日头寸上，问资本是多少——方向是<strong>情景 → 损失</strong>。反向压力测试（reverse stress test）把方向倒过来：先定义失败事件（资本充足率跌破门槛、流动性耗尽、保本产品穿地板、策略强制清盘），再在风险因子空间里寻找能导致该事件的情景集合，并评估其可信度。英国 FSA/PRA 与欧银 CEBS 在 2009–2010 年前后把这一程序写进银行内部资本与流动性评估的公开指引：它不是又一种 99% 分位数，而是对「模型认为不可能、但一旦发生会让企业无法继续」的显式搜索。本篇写识别问题、可信度约束，以及它与 Copula、相关性崩溃情景的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>记损失映射 \\(L=g(x)\\)，\\(x\\) 为风险因子变化。正向压力指定 \\(x^\\star\\)（历史一周、假设平行加息），计算 \\(L(x^\\star)\\)。反向指定阈值 \\(L^\\star\\)（例如一年利润、一级资本的某一比例），求集合</p> \\[\\mathcal{S}(L^\\star)=\\{x:\\ g(x)\\ge L^\\star\\}. \\]<p>\\(\\mathcal{S}\\) 一般是高维曲面外侧的一整块，不是一个点。任意挑一个使 \\(g(x)=L^\\star\\) 的 \\(x\\) 没有信息量：可以让单一名字跌 99%，也可以让所有因子各动一点点。问题是在 \\(\\mathcal{S}\\) 上加<strong>可信度</strong>（plausibility）与<strong>叙事</strong>（哪条融资链、哪组相关），使输出是少数可讨论的情景，而不是优化器的一个任意解。</p><p>失败事件必须预先定义，且与经营约束一致。交易台的「最大可接受单日亏损」与集团的「无法展期批发融资」不是同一 \\(L^\\star\\)。把反向压力做成「搜历史上使今日 ES 最大的 12 个月」，那是 FRTB 选压力期，对象仍是资本公式，不是企业失败。</p><h3 id="识别不足是设计特征" tabindex="-1">识别不足是设计特征 <a class="header-anchor" href="#识别不足是设计特征" aria-label="Permalink to &quot;识别不足是设计特征&quot;">​</a></h3><p>\\(x\\) 的维数远高于一个标量 \\(L^\\star\\)，逆问题先天欠定。这不是缺陷：真正要的是<strong>若干条机制不同的路径</strong>都能走到失败，好让管理层看到不只一种死法。欠定若用「最小欧氏范数的 \\(x\\)」来破，会得到所有因子都动一点的模糊情景，往往既不可交易也无法对冲。破欠定的合法约束来自经济结构：融资篮子必须一起动、曲线须保持无套利形状、流动性枯竭时深度下降，而不是来自 \\(\\ell_2\\) 正则。</p><p><span class="marginnote">反向压力的输出若只有一个「最坏 \\(x\\)」，多半是优化器选了惩罚函数，不是风险被识别了。最低交付应是一组情景：相关崩溃型、单一名称集中型、融资枯竭型、跳缺口型，各自达到同一 \\(L^\\star\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先固定 \\(g\\) 与 \\(L^\\star\\)。</strong> \\(g\\) 必须与日常损益归因同一套头寸与定价器，否则找到的 \\(x\\) 在真实账簿上走不出 \\(L^\\star\\)。线性希腊字母映射会漏凸性：反向搜到的利率平移可能在全定价下走不到失败，或反过来。对期权、预付、CPPI，必须全定价。\\(L^\\star\\) 写成可审计的会计或监管量，含税、含资金成本、含已经承诺的分红与回购。</p><p><strong>在 \\(\\mathcal{S}\\) 上搜索。</strong> 实务几条路。（1）历史：在长样本里找 \\(g(x_t)\\ge L^\\star\\) 的日期，当作已实现反向情景——样本外失败若从未出现，集合为空，不能因此宣称安全。（2）蒙特卡洛：从 Copula 或 FHS 抽 \\(x\\)，保留超过 \\(L^\\star\\) 的路径，再聚类成典型失败模式。（3）优化：最小化可信度惩罚（马氏距离、Copula 密度的负对数、或「与历史压力的偏离」），约束 \\(g(x)\\ge L^\\star\\)。第（3）条必须把相关结构写进惩罚，否则最优解会走相关矩阵的零特征向量——统计上「便宜」、经济上荒谬。</p><p><strong>可信度。</strong> 马氏距离 \\(x^\\top\\Sigma^{-1}x\\) 用平静期 \\(\\Sigma\\) 时，会把相关崩溃判成极不可信，而这正是危机的特征。应至少用压力期 \\(\\Sigma\\) 或厚尾 Copula 密度当惩罚，并单独放一条「强制融资篮子相关接近 1」的情景，见<a href="/quant/corr-break-scenario">相关性崩溃情景</a>。叙事层：每个定量 \\(x\\) 配一段机制（谁被迫卖、抵押品是谁、多长时间内无法对冲）。</p><h3 id="与正向压力、反向-covar-的接口" tabindex="-1">与正向压力、反向 CoVaR 的接口 <a class="header-anchor" href="#与正向压力、反向-covar-的接口" aria-label="Permalink to &quot;与正向压力、反向 CoVaR 的接口&quot;">​</a></h3><p>正向压力回答「指定 2008 年，我们亏多少」；反向回答「要亏掉生命线，市场得怎样」。两者应互相校准：若历史 2008 已经超过 \\(L^\\star\\)，反向集合非空且含真实路径，资本与业务限制必须先按正向结果收紧。若历史从未达到 \\(L^\\star\\)，反向给出的 \\(x\\) 是外推，应标明哪些因子的移动超出样本最大。Adrian–Brunnermeier 的 CoVaR 是条件分位，不是反向压力；但「系统已在其 VaR 时机构的条件损失」可以当作一种 \\(L^\\star\\) 的输入，问还需要多大的特异冲击才会失败。</p><p>流动性反向：失败可以是现金而非 P&amp;L。此时 \\(g\\) 是现金流映射，情景含保证金上调、担保品折价、客户赎回。市场反向与融资反向分开跑，再看交集——Brunnermeier–Pedersen 的螺旋正在交集上。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>正向模型的尾巴被历史与 Copula 参数截断：从未见过的联合极端，密度接近零，日常 VaR 不会报。反向把截断拿掉，问截断之外是否仍有经营上不可接受的点。机制是模型风险的显式化：不是「99.9% 足够」，而是「那 0.1% 以及模型赋权为零的区域，是否包含一种我们活不下去的死法」。</p><p>搜索算法的机制决定你会看见哪一种死法。\\(\\ell_2\\) 最小移动偏向分散的小冲击；\\(\\ell_1\\) 偏向少数因子的大冲击；按融资篮子分组的块正则偏向相关崩溃。应预先声明正则族，并报告多种正则下的情景，避免只交付让现有对冲看起来仍有效的那种。</p><p><span class="marginnote">CPPI 的反向问题特别干净：失败 = 缺口，因子 = 再平衡窗口内风险资产收益与无法交易时长。临界跌幅 \\(\\approx 1/m\\) 是解析的一阶答案，仿真再补跳跃与停牌。见 <a href="/quant/cppi-tipp">CPPI / TIPP</a>。</span></p><h3 id="治理-谁有权改" tabindex="-1">治理：谁有权改 \\(L^\\star\\) <a class="header-anchor" href="#治理-谁有权改" aria-label="Permalink to &quot;治理：谁有权改 $L^\\star$&quot;">​</a></h3><p>\\(L^\\star\\) 一松，反向集合变远，情景看起来「更极端、因此不必行动」。这是最常见的内部套利。\\(L^\\star\\) 应与恢复与处置计划、契约条款、监管最低资本绑死，修改须走与风险偏好相同的批准链。定量团队可以建议映射 \\(g\\) 的改进，不能在同一轮测试里既改门槛又改情景。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>反向压力不能替代日常限额与 FRTB 资本：它没有置信水平，不能加总进一个乘数。高维优化昂贵且不稳定，因子必须先压缩到可叙事的十到几十个（曲线关键点、信用指数、主要外汇、波动、融资利差），其余用映射。定价器若在极端 \\(x\\) 上不收敛，应先修定价，而不是把这些 \\(x\\) 从 \\(\\mathcal{S}\\) 里删掉——删掉的往往是真正的失败模式。</p><p>不要用反向压力去「证明」当前组合安全：空集合只说明在你的 \\(g\\)、你的因子空间、你的搜索预算下没找到，不说明不存在。不要把反向情景直接当交易观点去做空。不要在泄漏的全样本上搜 \\(x\\) 再宣称样本外稳健。</p><p><span class="marginnote">公开监管文本要求开展反向压力，并不规定唯一算法。模型卡应写：\\(L^\\star\\) 定义、因子清单、惩罚/Copula、聚类方法、与 2008/2020 历史路径的对照。缺这些，反向压力只是工作坊叙事。</span></p>',28)),(t(),p(d,null,{default:s(()=>[B(n,{id:"mermaid-80",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E9%A2%84%E5%85%88%E5%86%BB%E7%BB%93%E7%9A%84%E5%A4%B1%E8%B4%A5%E9%98%88%E5%80%BC%20L*%22%5D%20--%3E%20G%5B%22%E4%B8%8E%E6%97%A5%E5%B8%B8%E4%B8%80%E8%87%B4%E7%9A%84%E6%8D%9F%E5%A4%B1%E6%98%A0%E5%B0%84%20g%22%5D%0A%20%20G%20--%3E%20S%5B%22%E9%9B%86%E5%90%88%20%7Bx%3A%20g(x)%20%E2%89%A5%20L*%7D%22%5D%0A%20%20S%20--%3E%20H%5B%22%E5%8E%86%E5%8F%B2%E5%B7%B2%E5%AE%9E%E7%8E%B0%E8%B7%AF%E5%BE%84%22%5D%0A%20%20S%20--%3E%20MC%5B%22Copula%20%2F%20FHS%20%E6%8A%BD%E6%A0%B7%E8%81%9A%E7%B1%BB%22%5D%0A%20%20S%20--%3E%20OPT%5B%22%E5%B8%A6%E5%8F%AF%E4%BF%A1%E5%BA%A6%E6%83%A9%E7%BD%9A%E7%9A%84%E4%BC%98%E5%8C%96%22%5D%0A%20%20H%20--%3E%20NAR%5B%22%E6%9C%BA%E5%88%B6%E5%8F%99%E4%BA%8B%20%2B%20%E8%9E%8D%E8%B5%84%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20MC%20--%3E%20NAR%0A%20%20OPT%20--%3E%20NAR%0A%20%20NAR%20--%3E%20ACT%5B%22%E8%B5%84%E6%9C%AC%E3%80%81%E9%99%90%E9%A2%9D%E3%80%81%E4%B8%9A%E5%8A%A1%E9%99%90%E5%88%B6%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[r("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"反向压力从失败事件反推因子情景，补的是正向压力与分位数资本看不到的模型截断区。"),a("li",null,"逆问题欠定，必须用经济结构（融资篮子、无套利、流动性）而不是随意正则来筛选情景。"),a("li",null,"交付应是一组机制不同、均达到同一 \\(L^\\star\\) 的情景，并与历史压力对照。"),a("li",null,"\\(L^\\star\\) 与 \\(g\\) 须冻结并与经营、监管约束对齐；放宽门槛不是风险下降。"),a("li",null,[r("出处：CEBS, "),a("em",null,"Guidelines on Stress Testing"),r(", 2010；BCBS 对内部资本与流动性评估中压力测试的公开原则；FSA/PRA 对反向压力的监管论述；机制背景见 Brunnermeier and Pedersen, 2009。")])],-1))])}const L=o(A,[["render",h]]);export{C as __pageData,L as default};
